     String // COMPUTER_LAB | PRINTING | ATM | AUDITORIUM | FIRST_AID | STUDY_ROOM\n  buildingName String\n  roomNumber   String\n  floor        String\n  description  String\n  openingHours String\n  isAccessible Boolean  @default(true)\n  lat          Float\n  lng          Float\n  createdAt    DateTime @default(now())\n}\n\nmodel Event {\n  id               String   @id @default(uuid())\n  title            String\n  description      String\n  category         String // TECHNICAL | CULTURAL | SPORTS | WORKSHOPS | HACKATHONS | SEMINARS | CLUBS | COMPETITIONS | PLACEMENT | ACADEMIC\n  date             String // YYYY-MM-DD\n  startTime        String // HH:mm\n  endTime          String // HH:mm\n  locationName     String\n  locationId       String?\n  organizerName    String\n  organizerId      String?\n  imageUrl         String?\n  maxParticipants  Int      @default(100)\n  isFree           Boolean  @default(true)\n  registrationLink String?\n  createdAt        DateTime @default(now())\n\n  location  CampusLocation? @relation(fields: [locationId], references: [id])\n  organizer User?           @relation(\"EventOrganizer\", fields: [organizerId], references: [id])\n  rsvps     EventRsvp[]\n}\n\nmodel EventRsvp {\n  id        String   @id @default(uuid())\n  eventId   String\n  userId    String\n  status    String   @default(\"REGISTERED\") // REGISTERED | ATTENDED | CANCELLED\n  createdAt DateTime @default(now())\n\n  event Event @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([eventId, userId])\n}\n\nmodel LostItem {\n  id                String   @id @default(uuid())\n  userId            String\n  title             String\n  category          String // ELECTRONICS | ID_CARDS | WALLETS_BAGS | BOOKS_STATIONERY | KEYS | ACCESSORIES | OTHER\n  description       String\n  color             String\n  lostDate          String // YYYY-MM-DD\n  locationName      String\n  imageUrl          String?\n  contactPreference String   @default(\"IN_APP\") // IN_APP | EMAIL\n  status            String   @default(\"ACTIVE\") // ACTIVE | RESOLVED\n  createdAt         DateTime @default(now())\n\n  user    User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  matches ItemMatch[] @relation(\"LostItemMatches\")\n}\n\nmodel FoundItem {\n  id            String   @id @default(uuid())\n  userId        String\n  title         String\n  category      String // ELECTRONICS | ID_CARDS | WALLETS_BAGS | BOOKS_STATIONERY | KEYS | ACCESSORIES | OTHER\n  description   String\n  color         String\n  foundDate     String // YYYY-MM-DD\n  locationName  String\n  imageUrl      String?\n  contactMethod String   @default(\"CAMPUS_SECURITY_DESK\")\n  status        String   @default(\"ACTIVE\") // ACTIVE | CLAIMED\n  createdAt     DateTime @default(now())\n\n  user    User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  matches ItemMatch[] @relation(\"FoundItemMatches\")\n}\n\nmodel ItemMatch {\n  id              String   @id @default(uuid())\n  lostItemId      String\n  foundItemId     String\n  confidenceScore Int // 0 - 100 percentage\n  matchReason     String\n  status          String   @default(\"PENDING\") // PENDING | CONFIRMED | DISMISSED\n  createdAt       DateTime @default(now())\n\n  lostItem  LostItem  @relation(\"LostItemMatches\", fields: [lostItemId], references: [id], onDelete: Cascade)\n  foundItem FoundItem @relation(\"FoundItemMatches\", fields: [foundItemId], references: [id], onDelete: Cascade)\n}\n\nmodel Cafeteria {\n  id               String   @id @default(uuid())\n  name             String\n  locationName     String\n  lat              Float\n  lng              Float\n  openingHours     String\n  priceRange       String // ₹ | ₹₹ | ₹₹₹\n  rating           Float    @default(4.2)\n  imageUrl         String?\n  phone            String?\n  isVegetarianOnly Boolean  @default(false)\n  description      String?\n  createdAt        DateTime @default(now())\n\n  foodItems FoodItem[]\n}\n\nmodel FoodItem {\n  id           String   @id @default(uuid())\n  cafeteriaId  String\n  name         String\n  category     String // MEALS | SNACKS | BEVERAGES | DESSERTS | BREAKFAST\n  price        Float\n  isVeg        Boolean  @default(true)\n  isVegan      Boolean  @default(false)\n  isHealthy    Boolean  @default(false)\n  calories     Int?\n  popularScore Float    @default(4.0)\n  description  String?\n  imageUrl     String?\n  createdAt    DateTime @default(now())\n\n  cafeteria Cafeteria @relation(fields: [cafeteriaId], references: [id], onDelete: Cascade)\n}\n\nmodel RoommateProfile {\n  id                String   @id @default(uuid())\n  userId            String   @unique\n  preferredHostel   String // Ganga Hostel | Kaveri Hostel | Yamuna Hostel | Brahmaputra\n  roomType          String // SINGLE | DOUBLE | TRIPLE\n  sleepSchedule     String // EARLY_BIRD | NIGHT_OWL | FLEXIBLE\n  studyHabits       String // SILENT_SOLO | GROUP_STUDY | BALANCED\n  cleanliness       String // METICULOUS | MODERATE | RELAXED\n  foodPreference    String // VEGETARIAN | NON_VEGETARIAN | JAIN | VEGAN | ANY\n  noiseTolerance    String // LOW | MEDIUM | HIGH\n  smokingPreference String // NON_SMOKER | SMOKER | OUTSIDE_ONLY\n  pets              String // NO_PETS | PET_FRIENDLY\n  socialPreference  String // INTROVERT | EXTROVERT | AMBIVERT\n  budget            Int // Monthly budget range (e.g. 5000, 8000, 12000)\n  department        String\n  year              Int\n  bio               String\n  updatedAt         DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel RoommateConnection {\n  id                 String   @id @default(uuid())\n  requesterId        String\n  targetId           String\n  status             String   @default(\"PENDING\") // PENDING | ACCEPTED | DECLINED\n  compatibilityScore Int // 0 - 100\n  message            String?\n  createdAt          DateTime @default(now())\n\n  requester User @relation(\"SentConnections\", fields: [requesterId], references: [id], onDelete: Cascade)\n  target    User @relation(\"ReceivedConnections\", fields: [targetId], references: [id], onDelete: Cascade)\n\n  @@unique([requesterId, targetId])\n}\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  title     String\n  message   String\n  type      String // MATCH | EVENT | ROOMMATE | ALERT | ANNOUNCEMENT\n  isRead    Boolean  @default(false)\n  linkUrl   String?\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel AiConversation {\n  id        String   @id @default(uuid())\n  userId    String\n  title     String   @default(\"New Conversation\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user     User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  messages AiMessage[]\n}\n\nmodel AiMessage {\n  id             String   @id @default(uuid())\n  conversationId String\n  sender         String // USER | ASSISTANT\n  content        String\n  intent         String? // Intent classification\n  structuredData String? // JSON string containing rich cards/recommendations\n  createdAt      DateTime @default(now())\n\n  conversation AiConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n}\n\nmodel KnowledgeBase {\n  id        String   @id @default(uuid())\n  title     String\n  category  String // ACADEMICS | TIMINGS | EMERGENCY | HOSTEL | TRANSPORT | RULES | FACILITIES\n  content   String\n  keywords  String // Comma separated keywords\n  updatedAt DateTime @updatedAt\n}\n\nmodel Feedback {\n  id        String   @id @default(uuid())\n  userId    String\n  category  String // UI | AI_ACCURACY | NAVIGATION | FOOD | OTHER\n  rating    Int // 1-5\n  comment   String\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n",
